    (v_chapter, 'mcq', 'scenario', 'bank', 5, 'What physical quantity is defined as the product of an object''s intrinsic mass and its linear velocity vector?', '["Force","Impulse","Inertia","Momentum"]'::jsonb, 'D', 1, '7dda82b12897', null),
    (v_chapter, 'mcq', 'scenario', 'bank', 5, 'If a body''s acceleration is observed to be exactly zero, what must be true about the forces acting on it?', '["No forces exist","Net force is zero","Force is maximum","Only gravity acts"]'::jsonb, 'B', 1, 'dc12298b401c', null),
    (v_chapter, 'mcq', 'scenario', 'bank', 5, 'Newton''s laws of motion fail to provide accurate descriptions for objects moving at which speeds?', '["Very low speeds","Medium speeds","Near speed of light","Zero speed"]'::jsonb, 'C', 1, '166c0a932496', null),
